<script setup lang="ts">
import axios from 'axios';
import {onMounted,onUnmounted,ref} from 'vue';
import {api,errorMessage} from '../api';
import {amount} from '../catalog';
import type {SavedOrder} from '../sales';
import {readPending,savePending,clearPending} from '../lib/pendingRequests';
import {refundReversalText as t} from '../locales/es/refundReversal';
import AppDialog from './AppDialog.vue';
type Review={version:number;review_hash:string;allowed:boolean;invoice_number:string;currency:string;amount:string;credit_after:string};
type Pending={receiptId:number;refundId:number;payload:{request_key:string;version:number;review_hash:string;reason:string;confirmed_no_money:true}};
const props=defineProps<{root:string;actorId:number;orderId:number;receiptId:number;refundId:number;returnFocus:HTMLElement|null}>();const emit=defineEmits<{changed:[SavedOrder];closed:[]}>();
const endpoint=`${props.root}/sales/orders/${props.orderId}/returns/${props.receiptId}/refunds/${props.refundId}/reversal`;const journal=`bshop:refund-reversal:${props.actorId}:${props.root}:${props.orderId}`;
const busy=ref(false);const error=ref('');const notice=ref('');const reason=ref('');const confirmed=ref(false);const review=ref<Review|null>(null);const pending=ref<Pending|null>(null);let alive=true;
const explain=(e:unknown)=>axios.isAxiosError(e)&&e.response?.status===409&&typeof e.response.data?.message==='string'?e.response.data.message:errorMessage(e);
async function refresh(){if(busy.value||pending.value)return;busy.value=true;error.value='';try{const result=(await api.get(endpoint)).data.data;if(alive)review.value=result;}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
function finish(order:SavedOrder,recovered=false){if(!alive)return;pending.value=null;error.value='';notice.value=recovered?t.recovered:t.success;try{clearPending(journal);}catch{}emit('changed',order);}
async function send(){if(busy.value||notice.value)return;error.value='';if(!pending.value){if(!review.value?.allowed||!confirmed.value||reason.value.trim().length<5)return;const operation:Pending={receiptId:props.receiptId,refundId:props.refundId,payload:{request_key:crypto.randomUUID(),version:review.value.version,review_hash:review.value.review_hash,reason:reason.value,confirmed_no_money:true}};try{savePending(journal,operation as unknown as Record<string,unknown>);pending.value=operation;}catch{error.value=t.journalError;return;}}
    busy.value=true;try{finish((await api.post(endpoint,pending.value.payload)).data.data.order);}catch(e){if(alive){error.value=explain(e);if(axios.isAxiosError(e)&&e.response&&[409,422].includes(e.response.status)){pending.value=null;review.value=null;try{clearPending(journal);}catch{}}}}finally{if(alive)busy.value=false;}}
async function recover(){if(!pending.value||busy.value)return;busy.value=true;error.value='';try{finish((await api.get(`${endpoint}/requests/${pending.value.payload.request_key}`)).data.data.order,true);}catch(e){if(alive)error.value=axios.isAxiosError(e)&&e.response?.status===404?t.notConfirmed:explain(e);}finally{if(alive)busy.value=false;}}
onMounted(async()=>{const stored=readPending(journal) as unknown as Pending|null;if(stored?.receiptId===props.receiptId&&stored.refundId===props.refundId&&typeof stored.payload?.request_key==='string'&&stored.payload.confirmed_no_money===true){pending.value=stored;reason.value=stored.payload.reason;confirmed.value=true;await recover();}else await refresh();});onUnmounted(()=>{alive=false;});
</script>
<template><AppDialog :open="true" :title="t.title" :busy="busy" :return-focus="returnFocus" @close="emit('closed')"><p>{{ t.description }}</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p><p v-if="busy" role="status">{{ t.loading }}</p><p v-if="pending" class="notice">{{ t.pending }}</p><template v-if="review&&!notice"><p><strong>{{ t.reference(refundId) }}</strong> · {{ review.invoice_number }}</p><dl><dt>{{ t.amount }}</dt><dd>{{ amount(review.amount,review.currency) }}</dd><dt>{{ t.after }}</dt><dd>{{ amount(review.credit_after,review.currency) }}</dd></dl><p v-if="!review.allowed" class="notice">{{ t.blocked }}</p></template><template v-if="!notice"><label>{{ t.reason }}<textarea v-model="reason" minlength="5" maxlength="255" rows="3" :disabled="busy||!!pending"></textarea></label><label class="no-money-confirmation"><input v-model="confirmed" type="checkbox" :disabled="busy||!!pending"><span>{{ t.attestation }}</span></label></template><button v-if="pending" type="button" class="button secondary" :disabled="busy" @click="recover">{{ t.check }}</button><button v-else-if="!notice" type="button" class="button secondary" :disabled="busy" @click="refresh">{{ t.refresh }}</button><template #footer><button type="button" class="button secondary" :disabled="busy" @click="emit('closed')">{{ t.close }}</button><button v-if="!notice" type="button" class="button danger" :disabled="busy||(!pending&&(!review?.allowed||!confirmed||reason.trim().length<5))" @click="send">{{ pending?t.retry:t.confirm }}</button></template></AppDialog></template>
<style scoped>p,dt{overflow-wrap:anywhere}dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;margin:20px 0}dd{margin:0;font-weight:650;white-space:nowrap}label{display:grid;gap:10px;margin:20px 0}textarea{font-size:16px;min-height:110px}.no-money-confirmation{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid #e6ddef;border-radius:12px;min-height:48px;line-height:1.5;cursor:pointer}.no-money-confirmation input{width:24px;height:24px;flex-shrink:0}</style>
